"use client";

import { useEffect, useRef } from "react";

const VERTEX_SRC = `
attribute vec2 a_position;
void main() {
  gl_Position = vec4(a_position, 0.0, 1.0);
}
`;

// Weicher, langsamer Verlauf aus Value-Noise statt teurer Simplex-Noise:
// reicht für einen ruhigen Hintergrund und kostet kaum GPU-Zeit.
const FRAGMENT_SRC = `
precision highp float;
uniform vec2 u_resolution;
uniform float u_time;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
    u.y
  );
}

void main() {
  vec2 uv = gl_FragCoord.xy / u_resolution.xy;
  vec2 p = uv * 3.0;

  float n = 0.0;
  n += noise(p + u_time * 0.15) * 0.6;
  n += noise(p * 2.0 - u_time * 0.25) * 0.4;

  // Signal2Spec-Markenfarben: dunkles Navy (#0b1f3a) bis gedecktes Blau.
  vec3 colorA = vec3(0.043, 0.122, 0.527);
  vec3 colorB = vec3(0.145, 0.239, 0.896);
  vec3 color = mix(colorA, colorB, n);

  gl_FragColor = vec4(color, 1.0);
}
`;

